class Configuration {
  public getClientId(): string {
    const clientId = import.meta.env.IDENTITY_PROVIDER_APP_CLIENT_ID as
      | string
      | undefined;
    if (clientId === undefined || clientId === '') {
      throw new Error('CLIENT_ID not found in environment variables.');
    }
    return clientId;
  }

  public getAuthority(): string {
    const authority = import.meta.env.IDENTITY_PROVIDER_APP_AUTHORITY as
      | string
      | undefined;
    if (authority === undefined || authority === '') {
      throw new Error('AUTHORITY not found in environment variables.');
    }
    return authority;
  }

  public getRedirectUri(): string {
    const redirectUri = import.meta.env.APP_REDIRECT_URI as string | undefined;
    if (redirectUri === undefined || redirectUri === '') {
      throw new Error('REDIRECT_URI not found in environment variables.');
    }
    return redirectUri;
  }

  public getScopes(): string {
    const scopes = import.meta.env.IDENTITY_PROVIDER_APP_SCOPES as
      | string
      | undefined;
    if (scopes === undefined || scopes === '') {
      throw new Error('SCOPES not found in environment variables.');
    }
    return scopes;
  }

  public getResponseType(): string {
    return String(import.meta.env.IDENTITY_PROVIDER_APP_RESPONSE_TYPE);
  }

  public getAccessTokenExpiringNotificationTime(): number {
    const value
      = (import.meta.env.ACCESS_TOKEN_EXPIRING_REFRESH_SECONDS as
      | string
      | undefined) ?? '1800';
    return Number.parseInt(value, 10);
  }
}

